using System;
class AccidentTests {
 static int checks;
 static void Check(bool ok,string name){checks++;if(!ok){Console.WriteLine("FAIL "+name);Environment.Exit(1);}}
 static void Near(double a,double b,string name){Check(Math.Abs(a-b)<1e-8,name+": "+a+" != "+b);}
 static EconomyLedger Ledger(int cash=1000,double seconds=1200){return new EconomyLedger(new PrototypeSettings{startCash=cash,oneDay=true,days=3,daySeconds=(float)seconds,parking=0,initialFuel=50});}
 static void Main(){
  Check(typeof(EconomyLedger).GetMethod("ChargeAccident",new[]{typeof(string)})!=null,"accident charge API missing");
  Run();Console.WriteLine("AccidentTests PASS "+checks+" checks");
 }
 static object Call(object target,string name,params object[] args){var types=Array.ConvertAll(args,arg=>arg.GetType());return target.GetType().GetMethod(name,types).Invoke(target,args);}
 static bool Charge(EconomyLedger l,string id){return (bool)Call(l,"ChargeAccident",id);}
 static bool Complete(EconomyLedger l,string id){return (bool)Call(l,"CompleteAccident",id);}
 static void Run(){
  Check(typeof(AccidentState).GetField("stopSeconds")!=null&&typeof(AccidentState).GetField("targets")!=null,"persist stopping and multi-target fields");
  var state=new AccidentState();state.Validate();Check(!state.Locked&&state.Begin("S","ped"),"default and begin");state.Validate();Check(state.Locked&&!state.Begin("again","other"),"active rejects new event");state.ObserveContact(false,5);Check(state.contactLatched,"processing cannot rearm");Check(state.MarkStopped(false)&&!state.Complete(),"requires outcome and charge");state.chargeApplied=state.outcomeApplied=true;var stateCopy=state.Copy();Check(stateCopy.Complete()&&state.phase==AccidentPhase.Waiting,"copy independent");stateCopy.Validate();stateCopy.ObserveContact(false,.79);Check(!stateCopy.Begin("next","ped"),"short separation rejected");stateCopy.ObserveContact(true,1);stateCopy.ObserveContact(false,.4);stateCopy.ObserveContact(false,.4);Check(stateCopy.Begin("next","ped"),"all contacts absent rearms");stateCopy.chargeApplied=stateCopy.outcomeApplied=true;Check(stateCopy.MarkStopped(true),"pvp stopped");Near(stateCopy.AdvanceProcessing(100),45,"timer clamp");Check(stateCopy.Complete(),"pvp complete");stateCopy.Validate();stateCopy.remaining=double.NaN;bool invalid=false;try{stateCopy.Validate();}catch(ArgumentException){invalid=true;}Check(invalid,"invalid checkpoint rejected");
  var persisted=new AccidentState();persisted.Begin("multi","one");persisted.stopSeconds=5.1;persisted.recoveryRequired=true;persisted.outcome="cancelled";persisted.targets=new[]{"one","two"};var deep=persisted.Copy();deep.targets[1]="three";Check(persisted.targets[1]=="two"&&deep.stopSeconds==5.1&&deep.recoveryRequired&&deep.outcome=="cancelled","deep victim and safety snapshot");deep.Validate();deep.stopSeconds=double.PositiveInfinity;invalid=false;try{deep.Validate();}catch(ArgumentException){invalid=true;}Check(invalid,"invalid stop time");var oldState=new AccidentState{targets=null};oldState.Validate();Check(oldState.targets.Length==0,"legacy targets normalize");
  var l=Ledger();Check(Charge(l,"A"),"first charge");Check(l.Account.Cash==0&&l.Account.Debt==2000&&l.Account.Expense(1,"accident")==3000,"cash/debt split");Check(!Charge(l,"A")&&!Complete(l,"unknown")&&!Charge(l," "),"replay and invalid charge");
  var r=EconomyLedger.RestoreCampaign(l.Snapshot(),l.Account.Snapshot());Check(!Charge(r,"A"),"restored charge replay");double fuel=r.Account.Fuel;r.Care.Soil("dirt",15);r.Driver.drowsiness.visionSeconds=35;
  Check(Complete(r,"A"),"single completes");Near(r.Elapsed,45,"single time");Near(r.Driver.fatigue,13,"single fatigue");Near(r.Driver.satiety,76.25,"single satiety");Near(r.Account.Fuel,fuel,"no fuel");Check(r.Care.Cleanliness==85&&r.Driver.drowsiness.visionSeconds==35,"no cleaning/exposure reset");Near(r.Metrics.Capture().serviceSeconds,45,"service metrics");
  r=EconomyLedger.RestoreCampaign(r.Snapshot(),r.Account.Snapshot());Check(!Complete(r,"A")&&!Charge(r,"A"),"restored completion replay");Near(r.Elapsed,45,"no duplicate time");r.RequestClose();Check(r.Settle(),"settle");Check((int)typeof(DayRecord).GetField("accident").GetValue(r.Last)==3000&&r.Last.net==-3000,"expense breakdown");r=EconomyLedger.RestoreCampaign(r.Snapshot(),r.Account.Snapshot());Check((int)typeof(DayRecord).GetField("accident").GetValue(r.Last)==3000,"summary restore");Check(r.NextDay()&&!Complete(r,"A")&&!Charge(r,"A"),"prior-day event cannot replay");
  foreach(double start in new[]{26.0,25,11,10,0}){var a=Ledger();a.Driver.satiety=start;a.Driver.fatigue=0;var expected=a.Driver.Copy();expected.Advance(45);Charge(a,"H");Complete(a,"H");Near(a.Driver.fatigue,expected.fatigue,"hunger "+start);Near(a.Driver.satiety,expected.satiety,"satiety "+start);}
  var boundary=Ledger(0,10);Charge(boundary,"B");Complete(boundary,"B");Check(boundary.Driver.fatigue==100&&boundary.Account.Debt==3000,"budget fatigue and unfunded mandatory");
  var p=Ledger();Check(p.EnablePvpProfile(),"enable pvp");p.Driver.satiety=26;p.Driver.fatigue=0;var want=p.Driver.Copy();want.Advance(45,false,PvpConditionRules.FatigueMultiplier);Charge(p,"P");for(int i=0;i<450;i++)Call(p,"AdvanceAccidentProcessing",.1);Check(Complete(p,"P"),"pvp completes");Near(p.Elapsed,45,"pvp no duplicate time");Near(p.Driver.fatigue,want.fatigue,"pvp chunk hunger");Near(p.Driver.satiety,want.satiety,"pvp chunk satiety");Near(p.Account.Fuel,50,"pvp no fuel");Check(p.Care.Cleanliness==100,"pvp no dirt");
  Check(typeof(EconomyLedger).GetMethod("CompletePvpRepair")!=null&&typeof(EconomyLedger).GetMethod("CompletePvpTow")!=null,"PVP workshop completion API missing");
  var workshop=Ledger();workshop.EnablePvpProfile();workshop.Care.Damage.Impact(6);workshop.AdvanceAccidentProcessing(3);Check(workshop.Account.Cash==1000&&workshop.Account.Debt==0&&workshop.Care.Damage.Durability==85,"partial repair cancelled without charge or repair");workshop.AdvanceAccidentProcessing(14.5);double repairFatigue=workshop.Driver.fatigue;Check((bool)Call(workshop,"CompletePvpRepair","repair-done"),"complete pvp repair");Check(workshop.Account.Cash==0&&workshop.Account.Debt==2000&&workshop.Care.Damage.Durability==100,"repair completed cash and debt");Near(workshop.Elapsed,17.5,"repair no second time");Near(workshop.Driver.fatigue,repairFatigue,"repair no second fatigue");Near(workshop.Account.Fuel,50,"repair no idle fuel");Check(!(bool)Call(workshop,"CompletePvpRepair","repair-done"),"duplicate repair");workshop.Care.Damage.Impact(20);workshop.Care.Damage.Advance(.8,false);workshop.Care.Damage.Impact(20);workshop.AdvanceAccidentProcessing(30);Check((bool)Call(workshop,"CompletePvpTow","tow-done","bay"),"complete tow");Near(workshop.Elapsed,47.5,"tow no second time");Check(workshop.Account.Debt==5000&&workshop.Care.Damage.RepairBayId=="bay"&&workshop.Care.Damage.Durability==0,"tow completed no repair");Check(!(bool)Call(workshop,"CompletePvpTow","tow-done","bay"),"duplicate tow");var restoredWorkshop=EconomyLedger.RestoreCampaign(workshop.Snapshot(),workshop.Account.Snapshot());restoredWorkshop.EnablePvpProfile();Check(!(bool)Call(restoredWorkshop,"CompletePvpTow","tow-done","bay"),"restored tow replay");Check(!(bool)Call(Ledger(),"CompletePvpRepair","not-pvp")&&!(bool)Call(Ledger(),"CompletePvpTow","not-pvp","bay"),"pvp completion rejects single");restoredWorkshop.RequestClose();Check(!(bool)Call(restoredWorkshop,"CompletePvpRepair","late"),"closing cancels pending optional repair");
  var exposure=Ledger();exposure.Driver.fatigue=100;exposure.Driver.drowsiness.visionSeconds=150;Charge(exposure,"exposure");Complete(exposure,"exposure");Near(exposure.Driver.drowsiness.visionSeconds,180,"single processing reaches blackout exposure cap");
  var exposurePvp=Ledger();exposurePvp.EnablePvpProfile();exposurePvp.Driver.fatigue=100;exposurePvp.Driver.drowsiness.visionSeconds=150;exposurePvp.AdvanceAccidentProcessing(45);Near(exposurePvp.Driver.drowsiness.visionSeconds,180,"pvp processing reaches blackout exposure cap");
  var crossingExposure=Ledger();crossingExposure.Driver.fatigue=99;Charge(crossingExposure,"crossing");Complete(crossingExposure,"crossing");Near(crossingExposure.Driver.drowsiness.visionSeconds,30,"single exposure starts after15s fatigue crossing");
  var crossingPvp=Ledger();crossingPvp.EnablePvpProfile();crossingPvp.Driver.fatigue=99;crossingPvp.Driver.satiety=26;crossingPvp.AdvanceAccidentProcessing(45);Near(crossingPvp.Driver.drowsiness.visionSeconds,33,"pvp hunger boundary exposure starts after12s");
  var hungryExposure=Ledger();hungryExposure.Driver.fatigue=98;hungryExposure.Driver.satiety=26;Charge(hungryExposure,"hungry");Complete(hungryExposure,"hungry");Near(hungryExposure.Driver.drowsiness.visionSeconds,21,"hunger crossing exposure starts after24s");
  var budgetExposure=Ledger(1000,10);Charge(budgetExposure,"budget-exposure");Complete(budgetExposure,"budget-exposure");Near(budgetExposure.Driver.drowsiness.visionSeconds,35,"single budget exposure starts after10s");
  var chunkExposure=Ledger();chunkExposure.EnablePvpProfile();chunkExposure.Driver.fatigue=99;chunkExposure.Driver.satiety=26;for(int i=0;i<450;i++)chunkExposure.AdvanceAccidentProcessing(.1);Near(chunkExposure.Driver.drowsiness.visionSeconds,33,"chunked pvp exposure matches single interval");
  var noExposure=Ledger();Charge(noExposure,"awake");Complete(noExposure,"awake");Near(noExposure.Driver.drowsiness.visionSeconds,0,"below100 processing accrues no exposure");
  var safety=new AccidentState();safety.Begin("safety","ped");safety.MarkStopped(false);safety.chargeApplied=safety.outcomeApplied=true;safety.recoveryRequired=true;Check(!safety.Complete()&&safety.Locked,"unsafe recovery cannot complete");safety.recoveryRequired=false;Check(safety.Complete(),"resolved recovery can complete");
  var shortMatch=Ledger();shortMatch.EnablePvpProfile();Charge(shortMatch,"end");Call(shortMatch,"AdvanceAccidentProcessing",3.0);shortMatch.RequestClose();shortMatch.Settle();Check(shortMatch.Elapsed==3&&shortMatch.Account.Expense(1,"accident")==3000,"short match retains charge and actual time");
 }
}
